/*
 * A080844  G.f. is F^2, where F is g.f. for Fibonacci word (A003849).
 * https://oeis.org/A080844
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = ∑_{k=0}^{n} fibword(k) · fibword(n–k) where fibword is
 *            the Fibonacci word (A003849), i.e. a(n) is the self‑convolution
 *            of the 0/1 sequence generated by the morphism 0 → 01, 1 → 0
 * Range:     u8 n <= 92, u16 n <= 92, u32 n <= 92, u64 n <= 92, u128 n <= 92,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>

/* --- Fibonacci word storage -------------------------------------------- */
static uint8_t *fib = NULL;      /* bits of the Fibonacci word          */
static size_t fib_len = 0;        /* current length of fib                */

/* Ensure that fib has at least N+1 bits available.  Bits are generated
   incrementally by applying the morphism until the required length
   is reached.  Each expansion takes O(current_length) time.  */
static void ensure_fib(size_t N)
{
    if (fib_len > N)          /* already long enough */
        return;

    /* initial step: start with a single 0 */
    if (fib == NULL) {
        fib = (uint8_t *)malloc(1);
        fib[0] = 0;
        fib_len = 1;
        if (fib == NULL) return;   /* malloc failure – not handled further */
    }

    /* loop until the array is long enough */
    while (fib_len <= N) {
        size_t cnt0 = 0;
        for (size_t i = 0; i < fib_len; ++i)
            if (fib[i] == 0) ++cnt0;

        size_t new_len = fib_len + cnt0;          /* 0 → 01 adds one extra bit per zero */
        uint8_t *new_fib = (uint8_t *)malloc(new_len);
        if (new_fib == NULL)
            return;  /* malloc failure – not handled further */

        size_t pos = 0;
        for (size_t i = 0; i < fib_len; ++i) {
            if (fib[i] == 0) {
                new_fib[pos++] = 0;
                new_fib[pos++] = 1;
            } else {            /* fib[i] == 1 */
                new_fib[pos++] = 0;
            }
        }

        free(fib);
        fib = new_fib;
        fib_len = new_len;
    }
}

/* --- Convolution storage ---------------------------------------------- */
static seq_t *conv = NULL;      /* self‑convolution of fibword          */
static size_t conv_len = 0;      /* number of computed entries (conv_len=0 → none) */

/* Ensure that conv has entries up to index N inclusive.
   Convolution for new indices is computed lazily.  */
static void ensure_conv(size_t N)
{
    if (conv_len > N)          /* already computed */
        return;

    /* grow the storage */
    size_t new_cap = N + 1;
    seq_t *new_conv = (seq_t *)malloc(new_cap * sizeof(seq_t));
    if (new_conv == NULL)
        return;  /* malloc failure – not handled further */

    /* copy old values if any */
    if (conv != NULL && conv_len > 0)
        for (size_t i = 0; i < conv_len; ++i)
            new_conv[i] = conv[i];

    /* compute new entries */
    for (size_t n = conv_len; n <= N; ++n) {
        seq_t s = 0;
        for (size_t k = 0; k <= n; ++k) {
            /* each fibword entry is 0 or 1 */
            if (fib[k] && fib[n - k])
                ++s;
        }
        new_conv[n] = s;
    }

    /* replace the old array */
    free(conv);
    conv = new_conv;
    conv_len = new_cap;
}

/* --- Public sequence function ------------------------------------------ */
seq_t a(idx_t n)
{
    /* ensure necessary data */
    ensure_fib((size_t)n);
    ensure_conv((size_t)n);
    return conv[(size_t)n];
}
